import { createRequire } from "module"; const require = createRequire("<project>/flare/node_modules/"); export const { chromium } = require("playwright-core");
export async function ctx(b, opts={}) { return b.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2, extraHTTPHeaders:{"x-flare-test":"1"}, ...opts }); }
export async function dump(p){ return (await p.evaluate(()=>document.body.innerText)) + "\n--controls--\n" + (await p.$$eval("button,a,input,textarea,select", els=>els.filter(e=>e.offsetParent!==null||e.type==="file").map(e=>e.tagName+"|"+(e.type||"")+"|"+(e.innerText||e.getAttribute("aria-label")||e.placeholder||e.name||"").trim().replace(/\s+/g," ").slice(0,70)).join("\n"))); }
EOF
cat > s4.mjs <<'EOF'
import { chromium, ctx, dump } from "./lib.mjs";
const b = await chromium.launch({ channel: "chrome" });
const c = await ctx(b); const p = await c.newPage();
p.on("console", m=>{ if(m.type()==="error") console.log("CONSOLE ERR", m.text()); });
await p.goto("https://flare-outside.onrender.com/app/", {waitUntil:"networkidle", timeout:90000});
for (let i=2;i<=3;i++){ await p.getByRole("button",{name:"Next"}).click(); await p.waitForTimeout(800); await p.screenshot({path:`app-${i}.png`}); console.log("== step",i); console.log(await dump(p)); }
const btn = p.getByRole("button",{name:/Next|Start|Get started|Done/}).first();
if (await btn.count()) { await btn.click(); await p.waitForTimeout(1200); }
await p.screenshot({path:"app-4.png"}); console.log("== step 4"); console.log(await dump(p));
await c.storageState({path:"host-state.json"});
await b.close();
EOF
